import{_ as e,o as l,c as o,a5 as m}from"./chunks/framework.DJo0M80U.js";const q=JSON.parse('{"title":"elemntUI","description":"ElementUI中input回车触发页面刷新问题及其解决方法 在日常的开发过程中，你可能会遇到一个问题：在ElementUI的el form表单中，如果只存在一个el input输入框，当你输入值后按下回车，页面会发生刷新。这是因为当form元素中只有一个输入框时，按下回车将触。","frontmatter":{"title":"elemntUI","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","补充主题"],"description":"ElementUI中input回车触发页面刷新问题及其解决方法 在日常的开发过程中，你可能会遇到一个问题：在ElementUI的el form表单中，如果只存在一个el input输入框，当你输入值后按下回车，页面会发生刷新。这是因为当form元素中只有一个输入框时，按下回车将触。","sidebarWeight":1,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/ui/elemntUI.md"},"headers":[],"relativePath":"posts/Vue系统教程/09-补充主题/elemntUI.md","filePath":"posts/Vue系统教程/09-补充主题/elemntUI.md"}'),u={name:"posts/Vue系统教程/09-补充主题/elemntUI.md"};function r(n,t,i,a,p,s){return l(),o("div",null,[...t[0]||(t[0]=[m('<div><h1 id="elemntui" tabindex="-1">elemntUI <a class="header-anchor" href="#elemntui" aria-label="Permalink to &quot;elemntUI&quot;">​</a></h1><blockquote><p>本节目标：理解“elemntUI”的核心思路，并能把它用于实际开发或面试表达。 ElementUI中input回车触发页面刷新问题及其解决方法</p></blockquote><p>在日常的开发过程中，你可能会遇到一个问题：在ElementUI的el-form表单中，如果只存在一个el-input输入框，当你输入值后按下回车，页面会发生刷新。这是因为当form元素中只有一个输入框时，按下回车将触发表单的默认提交事件，这是W3C标准的规定。</p><p>解决方法： ElementUI也给出了解决方法。如果你希望阻止这一默认行为，可以在&lt;el-form&gt;标签上添加@submit.native.prevent。例如：</p><p>&lt;el-form :model=&quot;form&quot; ref=&quot;form&quot; label-width=&quot;200px&quot; class=&quot;form&quot; @submit.native.prevent &gt; &lt;el-form-item label=&quot;姓名&quot; prop=&quot;name&quot; &gt; &lt;el-input v-model.number=&quot;form.name&quot;&gt;&lt;/el-input&gt; &lt;/el-form-item&gt; &lt;el-form-item&gt; &lt;el-button type=&quot;primary&quot; @click=&quot;submit(&#39;form&#39;)&quot;&gt;提交&lt;/el-button&gt; &lt;el-button @click=&quot;reset(&#39;form&#39;)&quot;&gt;重置&lt;/el-button&gt; &lt;/el-form-item&gt; &lt;/el-form&gt; 然而，上述方法只是阻止了默认行为，如果你仍需要回车来提交表单，你可以通过以下方式解决：</p><p>&lt;el-form :model=&quot;form&quot; ref=&quot;form&quot; label-width=&quot;200px&quot; class=&quot;form&quot; ==@submit.native.prevent=&quot;() =&gt; submit(&#39;form&#39;)&quot;== &gt; &lt;el-form-item label=&quot;姓名&quot; prop=&quot;name&quot; &gt; &lt;el-input v-model.number=&quot;form.name&quot;&gt;&lt;/el-input&gt; &lt;/el-form-item&gt; &lt;el-form-item&gt; &lt;el-button type=&quot;primary&quot; ==native-type=&quot;submit&quot;==&gt;提交&lt;/el-button&gt; &lt;el-button @click=&quot;reset(&#39;form&#39;)&quot;&gt;重置&lt;/el-button&gt; &lt;/el-form-item&gt; &lt;/el-form&gt; 请注意以下几点：</p><ul><li>确保使用 @submit.native.prevent 阻止原生事件，执行方法为搜索按钮按click事件</li><li>搜索按钮需要被包裹在 el-form 中</li><li>移除搜索按钮的click事件</li><li>确保增加 native-type=&quot;submit&quot; 属性</li></ul><p>此外，原生的form表单的单input和form包裹el-input回车刷新的问题也可以解决，有以下几种方法：</p><ul><li>在form表单内再增加一个隐藏的input框，可以通过hidden定义隐藏的输入字段，或者通过CSS样式进行隐藏。</li><li>去掉输入框的回车事件（根据需求来定，有的需要回车事件提交表单来查询或者执行其他操作则该方法不适用）。</li><li>阻止表单默认提交事件。例如，使用onsubmit句柄返回false来阻止原生form内的input的默认提交事件。</li></ul><p>为了帮助大家更好地理解和解决这个问题，你可以参考ElementUI的官方解决这个回车刷新页面的方案，其开源地址为：</p><p><a href="https://github.com/ElemeFE/element/blob/a0e82aa8ac58d68e66992a5632b779a901436879/examples/docs/zh-CN/form.md" target="_blank" rel="noreferrer">https://github.com/ElemeFE/element/blob/a0e82aa8ac58d68e66992a5632b779a901436879/examples/docs/zh-CN/form.md</a></p><p>希望这些方法能够帮助你解决ElementUI中input回车触发页面刷新的问题。如果你有任何进一步的问题或需要其他帮助，欢迎随时提问。 ———————————————— 版权声明：本文为CSDN博主「Terence全栈开发」的原创文章，遵循CC 4.0 BY-SA版权协议，转载请附上原文出处链接及本声明。 原文链接：<a href="https://blog.csdn.net/qq_39997939/article/details/131048775" target="_blank" rel="noreferrer">https://blog.csdn.net/qq_39997939/article/details/131048775</a></p></div>',1)])])}const c=e(u,[["render",r]]);export{q as __pageData,c as default};
